import{_ as o,o as e,c as a,a2 as s}from"./chunks/framework.Crpw6aS5.js";const i="/assets/00-logto-logo.B9SQ3peo.png",r="/assets/01-logto-features.Cs2Mszjh.png",n="/assets/02-showcase-logto-auth-sdks.CtzX2raw.gif",l="/assets/03-showcase-logto-sign-in-experience.BWB_oieo.gif",g="/assets/04-showcase-logto-multi-tenancy.qyvoiefG.gif",b=JSON.parse('{"title":"Logto (logto-io/logto)","description":"Imported notes from the Logto open-source auth infrastructure GitHub repository","frontmatter":{"title":"Logto (logto-io/logto)","description":"Imported notes from the Logto open-source auth infrastructure GitHub repository"},"headers":[],"relativePath":"software-engineering/authentication/github-logto-io-logto.md","filePath":"software-engineering/authentication/github-logto-io-logto.md"}'),h={name:"software-engineering/authentication/github-logto-io-logto.md"};function p(c,t,d,u,k,f){return e(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="logto-logto-io-logto" tabindex="-1">Logto (logto-io/logto) <a class="header-anchor" href="#logto-logto-io-logto" aria-label="Permalink to &quot;Logto (logto-io/logto)&quot;">​</a></h1><p><img src="'+i+'" alt="Logto logo"></p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><ul><li>Type: webpage</li><li>Origin: <a href="https://github.com/logto-io/logto" target="_blank" rel="noreferrer">https://github.com/logto-io/logto</a></li><li>Imported: 2026-07-27</li><li>Images: 5 (logo PNG, features PNG, and 3 showcase GIFs saved under <code>./assets/github-logto-io-logto/</code>)</li></ul><h2 id="content" tabindex="-1">Content <a class="header-anchor" href="#content" aria-label="Permalink to &quot;Content&quot;">​</a></h2><p><a href="https://github.com/logto-io/logto" target="_blank" rel="noreferrer">Logto</a> is modern, open-source auth infrastructure for SaaS and AI apps. It builds on OIDC and OAuth 2.1 and aims to make production-ready auth straightforward, with multi-tenancy, enterprise SSO, and RBAC.</p><p>Useful links:</p><ul><li><a href="https://logto.io/" target="_blank" rel="noreferrer">Website</a></li><li><a href="https://cloud.logto.io/" target="_blank" rel="noreferrer">Cloud</a></li><li><a href="https://docs.logto.io" target="_blank" rel="noreferrer">Docs</a></li><li><a href="https://openapi.logto.io/" target="_blank" rel="noreferrer">OpenAPI</a></li><li><a href="https://blog.logto.io/" target="_blank" rel="noreferrer">Blog</a></li><li><a href="https://auth-wiki.logto.io/" target="_blank" rel="noreferrer">Auth wiki</a></li><li><a href="https://logto.io/subscribe" target="_blank" rel="noreferrer">Newsletter</a></li><li><a href="https://discord.gg/vRvwuwgpVX" target="_blank" rel="noreferrer">Discord</a></li></ul><p><img src="'+r+`" alt="Logto features overview"></p><h3 id="why-logto" tabindex="-1">Why Logto? <a class="header-anchor" href="#why-logto" aria-label="Permalink to &quot;Why Logto?&quot;">​</a></h3><p>Built for teams scaling SaaS, AI, and agent-based platforms without the usual auth headaches.</p><ul><li><strong>Multi-tenancy, enterprise SSO, and RBAC</strong> — ready to use, no workarounds.</li><li><strong>Pre-built sign-in flows</strong>, customizable UIs, and SDKs for 30+ frameworks.</li><li><strong>Full support for OIDC, OAuth 2.1, and SAML</strong> without the protocol pain.</li><li><strong>Works out-of-the-box for Model Context Protocol and agent-based AI architectures</strong>.</li></ul><p>See <a href="https://docs.logto.io/?ref=readme" target="_blank" rel="noreferrer">all features</a>.</p><h3 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h3><p>Pick a path:</p><ul><li><strong><a href="https://cloud.logto.io/?sign_up=true&amp;ref=readme" target="_blank" rel="noreferrer">Logto Cloud</a></strong> — fastest way to try Logto; fully managed, zero setup.</li><li><strong><a href="https://gitpod.io/#https://github.com/logto-io/demo" target="_blank" rel="noreferrer">Launch Logto in GitPod</a></strong> — start Logto OSS in seconds. Wait for <code>App is running at https://3002-...gitpod.io</code>, then open the URL starting with <code>https://3002-</code>.</li><li><strong>Local development:</strong></li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Using Docker Compose (requires Docker Desktop)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/logto-io/logto/HEAD/docker-compose.yml</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logto</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Using Node.js (requires PostgreSQL)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @logto</span></span></code></pre></div><p>Full OSS install guide: <a href="https://docs.logto.io/logto-oss/get-started-with-oss?ref=readme" target="_blank" rel="noreferrer">Get started with OSS</a>.</p><h3 id="integrate-anywhere" tabindex="-1">Integrate anywhere <a class="header-anchor" href="#integrate-anywhere" aria-label="Permalink to &quot;Integrate anywhere&quot;">​</a></h3><p>Logto supports apps, APIs, and services with industry-standard protocols.</p><ul><li><p><strong>SDKs for 30+ frameworks</strong>: React, Next.js, Angular, Vue, Flutter, Go, Python, and more.</p></li><li><p><strong>Connect to any IdP</strong>: Google, Facebook, Azure AD, Okta, and more.</p></li><li><p><strong>Flexible integration</strong>: SPAs, web apps, mobile apps, APIs, M2M, CLI tools.</p></li><li><p><strong>Ready for Model Context Protocol and agent-based architectures</strong>.</p></li><li><p><a href="https://docs.logto.io/quick-starts?ref=readme" target="_blank" rel="noreferrer">Explore quick starts</a></p></li><li><p><a href="https://docs.logto.io/integrations?ref=readme" target="_blank" rel="noreferrer">See all connectors</a></p></li></ul><h3 id="showcase" tabindex="-1">Showcase <a class="header-anchor" href="#showcase" aria-label="Permalink to &quot;Showcase&quot;">​</a></h3><p><strong>Developer-first SDKs</strong> — install in minutes with clear guides.</p><p><img src="`+n+'" alt="Logto auth SDK showcase"></p><p><strong>User-friendly auth flows</strong> — sign-up, sign-in, social login, Google One Tap, MFA, SSO.</p><p><img src="'+l+'" alt="Logto sign-in experience showcase"></p><p><strong>Multi-tenancy &amp; organizations</strong> — organization RBAC, member invites, just-in-time provisioning, and more.</p><p><img src="'+g+'" alt="Logto multi-tenancy showcase"></p><h3 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h3><p><a href="https://github.com/logto-io/logto/blob/master/LICENSE" target="_blank" rel="noreferrer">MPL-2.0</a>.</p><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key Takeaways&quot;">​</a></h2><ul><li>Open-source CIAM / auth stack (OIDC, OAuth 2.1, SAML) aimed at SaaS and AI apps, including MCP/agent use cases.</li><li>Ships multi-tenancy, enterprise SSO, RBAC, and 30+ framework SDKs out of the box.</li><li>Run via Logto Cloud, GitPod demo, Docker Compose, or <code>npm init @logto</code> with PostgreSQL.</li><li>License is MPL-2.0; docs and connectors live at docs.logto.io.</li></ul>',32)])])}const y=o(h,[["render",p]]);export{b as __pageData,y as default};
